package com.lianxibu.site.repository.jobs;
import com.lianxibu.site.domain.jobs.BacklogHistoryTelemetry.Mutation;import com.lianxibu.site.domain.protocol.*;import java.time.*;import java.time.temporal.ChronoUnit;import java.util.*;import javax.sql.DataSource;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.*;import org.springframework.transaction.support.TransactionSynchronizationManager;
/** Opt-in witness of native shared business commits, atomic with their original transaction. */
public final class JdbcBacklogMutationWitness {
 public static final String KEY="ops_backlog_mutation-v1";private static final Map<DataSource,Scope> ACTIVE=new IdentityHashMap<>();private static final long MAX=9007199254740991L;
 private JdbcBacklogMutationWitness(){}
 public static synchronized Scope open(DataSource source,Clock clock){Objects.requireNonNull(source);Objects.requireNonNull(clock);if(ACTIVE.containsKey(source))throw invalid();var scope=new Scope(source,clock);ACTIVE.put(source,scope);return scope;}
 static synchronized Scope capture(DataSource source){return ACTIVE.get(source);}
 public static final class Scope implements AutoCloseable{
  private final DataSource source;private final JdbcTemplate sql;private final Clock clock;private final String epoch=UUID.randomUUID().toString();private volatile boolean active=true;
  private Scope(DataSource source,Clock clock){this.source=source;sql=new JdbcTemplate(source);this.clock=clock;}
  public Mutation read(){if(!active||!TransactionSynchronizationManager.isActualTransactionActive()||!TransactionSynchronizationManager.isCurrentTransactionReadOnly()||!Integer.valueOf(TransactionDefinition.ISOLATION_REPEATABLE_READ).equals(TransactionSynchronizationManager.getCurrentTransactionIsolationLevel()))throw invalid();var row=row();if(row==null||!row.value().epoch().equals(epoch))return null;Instant now=clock.instant().truncatedTo(ChronoUnit.MICROS);if(row.value().changedAt().isAfter(now))throw invalid();return row.value();}
  private record Row(Mutation value,long revision){}
  private Row row(){var rows=sql.query("SELECT CASE WHEN OCTET_LENGTH(value_json) BETWEEN 1 AND 16384 THEN value_json ELSE NULL END,revision,updated_at FROM runtime_settings WHERE setting_key=?",(r,n)->{String raw=r.getString(1);long revision=r.getLong(2);if(raw==null||revision<1||revision>MAX||r.wasNull())throw invalid();var root=CanonicalJson.parse(raw);var fields=Set.of("schema_version","epoch","started_at","changed_at","sequence");WireValues.object(root,fields,fields);if(!"backlog-mutation-v1".equals(WireValues.text(root.get("schema_version"))))throw invalid();var value=new Mutation(WireValues.text(root.get("epoch")),WireValues.utcMicroseconds(root.get("started_at")),WireValues.utcMicroseconds(root.get("changed_at")),WireValues.nonnegativeInteger(root.get("sequence")));var updated=r.getTimestamp(3,Calendar.getInstance(TimeZone.getTimeZone("UTC")));if(updated==null||!updated.toInstant().equals(value.changedAt()))throw invalid();return new Row(value,revision);},KEY);if(rows.size()>1)throw invalid();return rows.isEmpty()?null:rows.getFirst();}
  void record(String action,String allocated){if(!active||!TransactionSynchronizationManager.isActualTransactionActive()||TransactionSynchronizationManager.isCurrentTransactionReadOnly()||!Integer.valueOf(TransactionDefinition.ISOLATION_READ_COMMITTED).equals(TransactionSynchronizationManager.getCurrentTransactionIsolationLevel()))throw invalid();Instant now=clock.instant().truncatedTo(ChronoUnit.MICROS);Row before=row();Mutation current;if(before==null||!before.value().epoch().equals(epoch)){if(before!=null&&(now.isBefore(before.value().changedAt())||before.revision()==MAX))throw invalid();current=new Mutation(epoch,now,now,0);}else{current=before.value();if(now.isBefore(current.changedAt()))throw invalid();}
   if(!observation(action,allocated)){if(current.sequence()==MAX)throw invalid();current=new Mutation(epoch,current.startedAt(),now,current.sequence()+1);}else if(before!=null&&before.value().epoch().equals(epoch))return;
   var value=tools.jackson.databind.json.JsonMapper.shared().createObjectNode();value.put("schema_version","backlog-mutation-v1");value.put("epoch",current.epoch());value.put("started_at",new java.time.format.DateTimeFormatterBuilder().appendInstant(6).toFormatter(java.util.Locale.ROOT).format(current.startedAt()));value.put("changed_at",new java.time.format.DateTimeFormatterBuilder().appendInstant(6).toFormatter(java.util.Locale.ROOT).format(current.changedAt()));value.put("sequence",current.sequence());String raw=JdbcFrozenInputs.canonical(value);final Mutation next=current;
   int changed=before==null?sql.update(c->{var s=c.prepareStatement("INSERT INTO runtime_settings(setting_key,value_json,revision,updated_at) VALUES(?,?,1,?)");s.setString(1,KEY);s.setString(2,raw);s.setTimestamp(3,java.sql.Timestamp.from(next.changedAt()),Calendar.getInstance(TimeZone.getTimeZone("UTC")));return s;}):sql.update(c->{var s=c.prepareStatement("UPDATE runtime_settings SET value_json=?,revision=revision+1,updated_at=? WHERE setting_key=? AND revision=?");s.setString(1,raw);s.setTimestamp(2,java.sql.Timestamp.from(next.changedAt()),Calendar.getInstance(TimeZone.getTimeZone("UTC")));s.setString(3,KEY);s.setLong(4,before.revision());return s;});if(changed!=1)throw invalid();
  }
  @Override public void close(){synchronized(JdbcBacklogMutationWitness.class){active=false;if(ACTIVE.get(source)==this)ACTIVE.remove(source);}}
  @Override public String toString(){return "BacklogMutationScope[redacted]";}
 }
 private static boolean observation(String action,String allocated){if(action==null||allocated==null)return false;if("collector-heartbeat".equals(allocated)&&action.matches("collector-heartbeat:[0-9a-f]{64}"))return true;if("collector-host-memory".equals(allocated)&&action.matches("collector-host-memory:[0-9a-f]{64}"))return true;var matcher=java.util.regex.Pattern.compile("(?:api|provider|source|recovery|java-memory|collector|backlog)-sample:([0-9a-f]{32}):[0-9]+").matcher(action);if(matcher.matches())return allocated.equals("ops_"+matcher.group(1));var rds=java.util.regex.Pattern.compile("rds-sample:([0-9a-f]{32}):OPS-(?:04|10):[0-9]+").matcher(action);return rds.matches()&&allocated.equals("ops_"+rds.group(1));}
 private static IllegalStateException invalid(){return new IllegalStateException("native backlog mutation witness unavailable");}
}
